class Bird:
    def fly(self):
        print("Bird flaps upward")

class Penguin(Bird):
    def fly(self):
        print("Penguin slides on ice")

zoo = [Bird(), Penguin()]
for animal in zoo:
    animal.fly()

class Vehicle:
    def describe(self):
        print("A wheeled machine")

class Truck(Vehicle):
    def describe(self):
        super().describe()
        print("Hauls freight")

t = Truck()
t.describe()

class Gem:
    def __init__(self, name):
        self.name = name

    def __str__(self):
        return "gem:" + self.name

    def __repr__(self):
        return "Gem(" + self.name + ")"

bag = [Gem("opal"), Gem("jade")]
print(bag[0])
print(bag)

class Crate:
    def __init__(self, codes):
        self.codes = codes

    def __len__(self):
        return len(self.codes) * 10

c = Crate(["a", "b", "c"])
print(len(c))

class Kilos:
    def __init__(self, value):
        self.value = value

    def __add__(self, other):
        return NotImplemented

class Pounds:
    def __init__(self, value):
        self.value = value

    def __radd__(self, other):
        return "converted"

a = Kilos(5)
b = Pounds(3)
print(a + b)

class Hiker:
    def __init__(self, name, km):
        self.name = name
        self.km = km

    def __lt__(self, other):
        return self.km < other.km

team = [Hiker("Rae", 12), Hiker("Kim", 7), Hiker("Val", 20)]
for h in sorted(team):
    print(h.name, h.km)

class Chip:
    def __init__(self, code):
        self.code = code

    def __str__(self):
        return "CHIP-" + self.code

    def __repr__(self):
        return "Chip(" + self.code + ")"

c = Chip("X1")
print(str(c))
print(repr(c))
print([c])

class Load:
    def __init__(self, tons):
        self.tons = tons

    def __gt__(self, other):
        print("checking")
        return self.tons > other.tons

heavy = Load(9)
light = Load(4)
print(heavy > light)
print(heavy < light)
